set -euo pipefail; EXPECTED=5d3977850e10ee9399a1c0aacdbcbac4c1a30139; test "$(git rev-parse HEAD)" = "$EXPECTED"; ADB=/opt/homebrew/bin/adb; TARGET=RFCT70L7E8J; test "$("$ADB" -s "$TARGET" get-state)" = device; PID="$("$ADB" -s "$TARGET" shell pidof link.localclimate.app | tr -d '\r')"; test -n "$PID"; "$ADB" -s "$TARGET" forward --remove tcp:9222 >/dev/null 2>&1 || true; "$ADB" -s "$TARGET" forward tcp:9222 localabstract:webview_devtools_remote_${PID}; sleep 1; node - <<'NODE'
const { execFileSync } = require('node:child_process');
if (typeof WebSocket === 'undefined') { console.error('NO_GLOBAL_WEBSOCKET'); process.exit(2); }
const targets = JSON.parse(execFileSync('curl', ['-fsS', 'http://127.0.0.1:9222/json'], { encoding: 'utf8' }));
if (!targets.length || !targets[0].webSocketDebuggerUrl) { console.error('NO_CDP_TARGET'); process.exit(3); }
const ws = new WebSocket(targets[0].webSocketDebuggerUrl);
const timer = setTimeout(() => { console.error('CDP_TIMEOUT'); process.exit(4); }, 10000);
ws.addEventListener('open', () => {
  const expression = `JSON.stringify({
    title: document.title,
    url: location.href,
    bodyText: document.body.innerText,
    headings: [...document.querySelectorAll('h1,h2,h3')].map(x => x.innerText),
    buttons: [...document.querySelectorAll('button')].map(x => ({text:x.innerText, aria:x.getAttribute('aria-label'), title:x.getAttribute('title')})),
    articles: [...document.querySelectorAll('article')].map(x => x.innerText),
    localStorageKeys: Object.keys(localStorage)
  })`;
  ws.send(JSON.stringify({ id: 1, method: 'Runtime.evaluate', params: { expression, returnByValue: true } }));
});
ws.addEventListener('message', (event) => {
  const msg = JSON.parse(String(event.data));
  if (msg.id !== 1) return;
  clearTimeout(timer);
  if (msg.result?.exceptionDetails) { console.error(JSON.stringify(msg.result.exceptionDetails)); process.exit(5); }
  const value = msg.result?.result?.value;
  if (!value) { console.error('EMPTY_RUNTIME_VALUE'); process.exit(6); }
  const parsed = JSON.parse(value);
  console.log('--- PHONE DOM SNAPSHOT ---');
  console.log(JSON.stringify(parsed, null, 2));
  const body = parsed.bodyText || '';
  console.log('HAS_GNIAZDKA=' + body.includes('Gniazdka'));
  console.log('ADD_AUTOMATION_COUNT=' + (body.match(/Dodaj automatykę/g) || []).length);
  console.log('ARTICLE_COUNT=' + parsed.articles.length);
  console.log('LOCAL_STORAGE_KEYS=' + parsed.localStorageKeys.join(','));
  ws.close();
});
NODE
echo '--- PROCESS ---'; "$ADB" -s "$TARGET" shell pidof link.localclimate.app; echo '--- FATALS ---'; "$ADB" -s "$TARGET" logcat -d --pid="$PID" -v brief '*:E' | grep -E 'FATAL EXCEPTION|AndroidRuntime|chromium.*ERROR' || true
